<script>
const kategoriKas=@json($kategori),selectJenisKas=document.getElementById('jenis'),selectKategoriKas=document.getElementById('kategori-akun'),kategoriKasTersimpan=@json(old('kategori_akun'));
function perbaruiKategoriKas(){if(!selectJenisKas||!selectKategoriKas)return;const daftar=kategoriKas[selectJenisKas.value]||[];selectKategoriKas.replaceChildren(new Option('Pilih Kategori Akun',''));daftar.forEach((kategori)=>selectKategoriKas.add(new Option(kategori,kategori,false,kategori===kategoriKasTersimpan)))}
selectJenisKas?.addEventListener('change',perbaruiKategoriKas);perbaruiKategoriKas();
</script>
